PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE clicks (   id INTEGER PRIMARY KEY AUTOINCREMENT,   product_id TEXT NOT NULL,   timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,   referrer TEXT,   utm_source TEXT,   utm_medium TEXT,   user_agent TEXT,   ip TEXT , event_type TEXT DEFAULT 'click');
CREATE TABLE conversions (   id INTEGER PRIMARY KEY AUTOINCREMENT,   product_id TEXT NOT NULL,   commission REAL,   order_id TEXT UNIQUE,   status TEXT DEFAULT 'pending',   timestamp DATETIME DEFAULT CURRENT_TIMESTAMP );
DELETE FROM sqlite_sequence;
CREATE INDEX idx_clicks_product ON clicks(product_id);
CREATE INDEX idx_conversions_product ON conversions(product_id);
